        Map<String, Integer> time = new HashMap<>();
        time.put("compile", 2);
        time.put("test", 5);

        Deque<String> work = new ArrayDeque<>(unique);
        while (!work.isEmpty()) {
            String task = work.removeFirst();
            System.out.println(task + " -> " + time.get(task));
        }
    }
}

