public class Main {
    public static void main(String[] args) {
        List<String> input = List.of("B", "A", "B", "C");

        Set<String> hash = new HashSet<>(input);
        Set<String> insertion = new LinkedHashSet<>(input);
        Set<String> sorted = new TreeSet<>(input);

        System.out.println(hash);      // order not guaranteed
        System.out.println(insertion); // [B, A, C]
        System.out.println(sorted);    // [A, B, C]
        System.out.println(sorted.ceiling("BB")); // C
    }
}

