    public static void main(String[] args) {
        Comparator<Job> order = Comparator
                .comparingInt(Job::priority)
                .thenComparing(Job::name);

        Queue<Job> jobs = new PriorityQueue<>(order);
        jobs.offer(new Job("report", 2));
        jobs.offer(new Job("incident", 1));
        jobs.offer(new Job("email", 3));

        while (!jobs.isEmpty()) {
            System.out.println(jobs.poll());
        }
    }
}

